export class AudioEngine{
  constructor(){this.ctx=null;this.master=null;this.started=false;this.enabled=false;this.scene=0;this.mode='neon';this.step=0;this.timer=null;this.narrationTimer=null;this.nodes=[];this.wind=new Audio('./assets/audio/mars-wind.oga');this.wind.loop=true;this.wind.volume=0;this.callout=new Audio('./assets/audio/srt-opening-callout.wav');this.callout.volume=.96;this.calloutPlayed=false;this.narrations=[null,...Array.from({length:6},(_,i)=>new Audio(`./assets/audio/tasks/task-${String(i+1).padStart(2,'0')}.wav`))];this.narrations.slice(1).forEach(x=>{x.preload='auto';x.volume=.96;x.load()});this.playedNarrations=new Set();this.activeVoice=null;}
  async start(){
    if(!this.ctx){
      this.ctx=new (window.AudioContext||window.webkitAudioContext)();
      this.master=this.ctx.createGain();this.master.gain.value=0;
      const comp=this.ctx.createDynamicsCompressor();comp.threshold.value=-18;comp.knee.value=12;comp.ratio.value=4;comp.attack.value=.01;comp.release.value=.3;
      this.master.connect(comp).connect(this.ctx.destination);this.buildBed();this.startClock();
    }
    await this.ctx.resume();this.started=true;this.enabled=true;this.master.gain.cancelScheduledValues(this.ctx.currentTime);this.master.gain.linearRampToValueAtTime(.72,this.ctx.currentTime+.8);this.syncScene();this.playOpeningCallout();
  }
  playOpeningCallout(){if(this.calloutPlayed)return;this.calloutPlayed=true;const restore=()=>{if(!this.ctx||!this.enabled)return;const t=this.ctx.currentTime;this.master.gain.cancelScheduledValues(t);this.master.gain.linearRampToValueAtTime(.72,t+1.2)};const t=this.ctx.currentTime;this.master.gain.cancelScheduledValues(t);this.master.gain.linearRampToValueAtTime(.2,t+.35);this.callout.addEventListener('ended',restore,{once:true});this.callout.play().catch(restore)}
  playNarration(scene=this.scene,force=false){const voice=this.narrations[scene];if(!voice||!this.enabled||(!force&&this.playedNarrations.has(scene)))return false;if(this.activeVoice&&this.activeVoice!==voice){this.activeVoice.pause();this.activeVoice.currentTime=0}this.activeVoice=voice;this.playedNarrations.add(scene);voice.currentTime=0;const restore=()=>{if(!this.ctx||!this.enabled)return;const t=this.ctx.currentTime;this.master.gain.cancelScheduledValues(t);this.master.gain.linearRampToValueAtTime(.72,t+.8)};if(this.ctx){const t=this.ctx.currentTime;this.master.gain.cancelScheduledValues(t);this.master.gain.linearRampToValueAtTime(.15,t+.25)}const begin=()=>{voice.removeEventListener('canplay',begin);voice.addEventListener('ended',restore,{once:true});voice.play().catch(()=>{this.playedNarrations.delete(scene);restore()})};if(voice.readyState>=2)begin();else{voice.addEventListener('canplay',begin,{once:true});voice.load()}return true}
  buildBed(){
    const now=this.ctx.currentTime;
    this.drone=this.ctx.createGain();this.drone.gain.value=.18;this.drone.connect(this.master);
    [43.65,65.41,87.31].forEach((f,i)=>{const o=this.ctx.createOscillator(),g=this.ctx.createGain(),p=this.ctx.createStereoPanner();o.type=i===0?'sine':'triangle';o.frequency.value=f;g.gain.value=[.28,.08,.04][i];p.pan.value=[-.2,.22,-.45][i];o.connect(g).connect(p).connect(this.drone);o.start(now);this.nodes.push(o)});
    const length=this.ctx.sampleRate*2,buf=this.ctx.createBuffer(1,length,this.ctx.sampleRate),d=buf.getChannelData(0);for(let i=0;i<length;i++)d[i]=(Math.random()*2-1)*(.6+.4*Math.sin(i/3100));
    this.noise=this.ctx.createBufferSource();this.noise.buffer=buf;this.noise.loop=true;const filter=this.ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=180;filter.Q.value=.8;this.noiseGain=this.ctx.createGain();this.noiseGain.gain.value=.055;this.noise.connect(filter).connect(this.noiseGain).connect(this.master);this.noise.start();
  }
  startClock(){clearInterval(this.timer);const bpm={neon:108,void:76,dawn:92}[this.mode]||108,beat=60000/bpm/2;this.timer=setInterval(()=>this.tick(),beat)}
  setMode(mode){if(!['neon','void','dawn'].includes(mode))return;this.mode=mode;this.step=0;if(this.ctx){this.startClock();this.syncScene()}}
  tick(){if(!this.enabled||!this.ctx)return;const s=this.step++%16;
    if(this.mode==='void'){if([0,8].includes(s))this.bass(this.scene>=4?36.71:43.65,.18);if([3,11].includes(s))this.chime(this.scene===5?174.61:220,.075);if(this.scene===4&&s%4===0)this.heartbeat();return}
    if(this.mode==='dawn'){if([0,4,8,12].includes(s))this.kick(this.scene===4?.45:.62);if([2,6,10,14].includes(s))this.hat(.1);if([0,4,8,12].includes(s))this.bass([43.65,51.91,58.27,51.91][s/4],.2);if([1,5,9,13].includes(s))this.chime([261.63,311.13,349.23,311.13][(s-1)/4],.07);return}
    if(this.scene===0){if([0,3,6,8,11,14].includes(s))this.kick(s===0?1:.7);if([2,6,10,14].includes(s))this.hat();if([0,4,8,12].includes(s))this.bass([43.65,43.65,51.91,38.89][s/4]);if([7,15].includes(s))this.chime(s===7?261.63:311.13,.12)}else if(this.scene===2){if(s%4===0)this.kick(.85);if(s%2===0)this.hat(.35)}else if(this.scene===3){if([0,5,8,13].includes(s))this.bass(s<8?43.65:49,.22);if([3,11].includes(s))this.chime(s===3?220:261.63,.08)}else if(this.scene===4){if(s%4===0)this.heartbeat();if(s===14)this.hat(.22)}else if(this.scene===5){if([0,8].includes(s))this.chime(s?196:174.61,.06)}}
  kick(force=1){const t=this.ctx.currentTime,o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type='sine';o.frequency.setValueAtTime(110,t);o.frequency.exponentialRampToValueAtTime(38,t+.18);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.38*force,t+.008);g.gain.exponentialRampToValueAtTime(.0001,t+.28);o.connect(g).connect(this.master);o.start(t);o.stop(t+.3)}
  bass(freq,level=.32){const t=this.ctx.currentTime,o=this.ctx.createOscillator(),f=this.ctx.createBiquadFilter(),g=this.ctx.createGain();o.type='sawtooth';o.frequency.value=freq;f.type='lowpass';f.frequency.setValueAtTime(260,t);f.frequency.exponentialRampToValueAtTime(75,t+.26);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(level,t+.015);g.gain.exponentialRampToValueAtTime(.0001,t+.36);o.connect(f).connect(g).connect(this.master);o.start(t);o.stop(t+.38)}
  hat(level=.22){const t=this.ctx.currentTime,len=this.ctx.sampleRate*.045,b=this.ctx.createBuffer(1,len,this.ctx.sampleRate),d=b.getChannelData(0);for(let i=0;i<len;i++)d[i]=Math.random()*2-1;const src=this.ctx.createBufferSource(),hp=this.ctx.createBiquadFilter(),g=this.ctx.createGain();src.buffer=b;hp.type='highpass';hp.frequency.value=6500;g.gain.setValueAtTime(level,t);g.gain.exponentialRampToValueAtTime(.0001,t+.05);src.connect(hp).connect(g).connect(this.master);src.start(t)}
  chime(freq,level=.1){const t=this.ctx.currentTime,o=this.ctx.createOscillator(),g=this.ctx.createGain(),p=this.ctx.createStereoPanner();o.type='sine';o.frequency.value=freq;p.pan.value=Math.random()*.9-.45;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(level,t+.03);g.gain.exponentialRampToValueAtTime(.0001,t+1.7);o.connect(g).connect(p).connect(this.master);o.start(t);o.stop(t+1.8)}
  heartbeat(){this.kick(.45);setTimeout(()=>this.kick(.25),130)}
  feedback(kind='tap',pan=0){if(!this.enabled||!this.ctx)return;const t=this.ctx.currentTime,o=this.ctx.createOscillator(),g=this.ctx.createGain(),p=this.ctx.createStereoPanner();p.pan.value=pan;o.type=kind==='success'?'sine':'square';o.frequency.setValueAtTime(kind==='error'?96:kind==='success'?520:310,t);if(kind==='success')o.frequency.exponentialRampToValueAtTime(780,t+.18);else o.frequency.exponentialRampToValueAtTime(kind==='error'?48:190,t+.1);g.gain.setValueAtTime(.12,t);g.gain.exponentialRampToValueAtTime(.0001,t+(kind==='success'?.45:.12));o.connect(g).connect(p).connect(this.master);o.start(t);o.stop(t+.5)}
  impact(){if(!this.enabled||!this.ctx)return;this.kick(1.7);this.bass(32,.48)}
  setScene(n){this.scene=n;this.syncScene();clearTimeout(this.narrationTimer);if(n>0)this.narrationTimer=setTimeout(()=>this.playNarration(n),900)}
  syncScene(){if(!this.ctx)return;const t=this.ctx.currentTime;const drone=[.2,.1,.18,.12,.08,.055,.1][this.scene];this.drone.gain.cancelScheduledValues(t);this.drone.gain.linearRampToValueAtTime(drone,t+1.4);this.noiseGain.gain.cancelScheduledValues(t);this.noiseGain.gain.linearRampToValueAtTime(this.scene===2?.15:this.scene===4?.12:.045,t+1);if(this.scene===5&&this.enabled){this.wind.play().catch(()=>{});this.fadeWind(.42)}else this.fadeWind(0)}
  fadeWind(target){const from=this.wind.volume,started=performance.now(),dur=1400;const f=now=>{const p=Math.min(1,(now-started)/dur);this.wind.volume=from+(target-from)*p;if(p<1)requestAnimationFrame(f);else if(target===0)this.wind.pause()};requestAnimationFrame(f)}
  async toggle(){if(!this.started){await this.start();return true}this.enabled=!this.enabled;const t=this.ctx.currentTime;this.master.gain.cancelScheduledValues(t);this.master.gain.linearRampToValueAtTime(this.enabled?.72:0,t+.35);if(this.enabled){await this.ctx.resume();this.syncScene()}else this.fadeWind(0);return this.enabled}
}
